import AddProduct from "@/components/SettingsDialogs/AddProduct.vue";
import EditProduct from "@/components/SettingsDialogs/EditProduct.vue";
import DeleteProduct from "@/components/SettingsDialogs/DeleteProduct.vue";
import { create_list_edit_delete_products } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    AddProduct,
    SnackBar,
    EditProduct,
    DeleteProduct
  },
  data() {
    return {
      productHeaders: [{
        text: "Logo",
        value: "product_logo_url",
        sortable: false
      }, {
        text: "Name",
        value: "product_name",
        sortable: false
      }, {
        text: "Description",
        value: "product_description",
        sortable: false
      }, {
        text: "URL",
        value: "product_link",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      fixed: true,
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      createProductDialog: false,
      SnackBarComponent: {},
      editProductDialogue: false,
      rowInfo: {},
      deleteProductDialogue: false,
      height: 0
    };
  },
  created() {
    this.fetch_territories();
    this.height = window.innerHeight - 310;
  },
  methods: {
    add_territory() {
      this.componentCheck = 1;
      this.createProductDialog = true;
    },
    edit_territory(value) {
      this.rowInfo = value;
      this.componentCheck = 2;
      this.editProductDialogue = true;
    },
    open_deletedailog(value) {
      this.rowInfo = value;
      this.componentCheck = 3;
      this.deleteProductDialogue = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createProductDialog = false;
      this.editProductDialogue = false;
      this.deleteProductDialogue = false;
      this.fetch_territories();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_territories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_products, {
          input: {
            action_type: "LIST_PRODUCT",
            // organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
          // product_name: "",
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_products);
        this.tableLoading = false;
        this.tableData = response.data;
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
